TEST_CATEGORIES = [
"Concrete","Cement","Aggregates","Bricks & Blocks","Steel","Soil"
]

def list_tests(category="", test_type=""):
    items = TEST_CATALOG.get(category, []) if category else [x for v in TEST_CATALOG.values() for x in v]
    if test_type:
        items = [x for x in items if test_type.lower() in x.get("type","").lower()]
    return items

def get_test(category, name):
    for item in TEST_CATALOG.get(category, []):
        if item["name"].lower() == name.lower():
            return item
    return None
